import unittest
from io import BytesIO
from zipfile import ZipFile
from bundle.service import load_texts

def zipped(entries):
    output=BytesIO()
    with ZipFile(output,'w') as archive:
        for name,data in entries: archive.writestr(name,data)
    return output.getvalue()

class Bundle(unittest.TestCase):
    def test_paths_and_encoding(self):
        blob=zipped([('east/note.txt','你好'.encode()),('west/note.txt',b'\xef\xbb\xbfwest'),('./docs//a.txt',b'A'),('empty/',b''),('raw.bin',b'\xff'),('UP.TXT',b'ignore')])
        self.assertEqual(load_texts(blob),{'east/note.txt':'你好','west/note.txt':'west','docs/a.txt':'A'})
        self.assertEqual(load_texts(zipped([])),{})
    def test_reject_paths_and_duplicates(self):
        for name in ['C:/out.bin','C:note.txt','/abs.txt','a/../out.bin','..\\out.txt','../dir/']:
            with self.assertRaises(ValueError): load_texts(zipped([(name,b'X')]))
        with self.assertRaises(ValueError): load_texts(zipped([('a.txt',b'A'),('./a.txt',b'B')]))
        with self.assertRaises(UnicodeDecodeError): load_texts(zipped([('bad.txt',b'\xff')]))

if __name__ == '__main__':
    unittest.main()

