import re

def normalize(name):
    if re.match(r'^[A-Za-z]:', name) or name.startswith('/') or '\\' in name or '..' in name.split('/'):
        raise ValueError('unsafe archive path')
    return '/'.join(part for part in name.split('/') if part not in ('','.'))

