from .reader import entries

def load_texts(blob):
    result = {}
    for name, data in entries(blob):
        if not name.endswith('.txt'):
            continue
        if name in result:
            raise ValueError('duplicate text path')
        result[name] = data.decode('utf-8-sig')
    return result

